  'nextstep': {
    short: 'NextStep', field: 'social', fieldName: 'Social Media Design', label: 'Social media design', cover: 'cs-ns-cover.jpg',
    title: 'Building a career brand that makes progress feel possible.',
    intro: 'NextStep is a self-initiated concept project for a fictional career development platform. I created the brand\'s social media direction to explore how career advice, educational content, and campaign messaging could live within one recognizable, human-centered visual system, not just a collection of isolated posts.',
    meta: [['Company', 'NextStep (concept)'], ['Role', 'Social Media Designer'], ['Industry', 'Career Development'], ['Timeline', 'Aug 2026']],
    blocks: [
      { type: 'cards', label: 'The challenge', title: 'Career content is useful. The problem is making people stop long enough to care.', cols: 3, numbered: true,
        body: 'Career feeds often fall into two extremes: dense educational graphics that feel institutional, or motivational content that looks polished but says very little. I wanted NextStep to sit between both: credible enough to teach, approachable enough to engage, and consistent enough to become recognizable in-feed.',
        items: [
          { t: 'Make advice scannable', d: 'Turn broad career topics into clear, single-minded messages that can be understood within seconds.' },
          { t: 'Build recognition', d: 'Create a repeatable visual language without making every post look like the same template.' },
          { t: 'Keep it human', d: 'Use people, environments, and career moments so the platform feels like guidance for real lives, not corporate stock content.' },
        ] },
      { type: 'cards', label: 'Creative direction', title: 'One visual system, multiple ways to tell the story.', cols: 3, tone: 'soft',
        body: 'I defined a social-first visual direction built around confident blue, optimistic yellow, oversized typography, soft gradients, and professional lifestyle imagery. Color and typography create recognition, while composition changes from post to post so the system stays flexible rather than template-driven.',
        items: [
          { t: 'Editorial hierarchy', d: 'Large headlines create immediate entry points; supporting copy stays intentionally short.' },
          { t: 'Career-world imagery', d: 'City, campus, workplace, CV, and billboard scenes connect abstract ambition to recognizable moments.' },
          { t: 'Flexible brand devices', d: 'Glass panels, message bubbles, cards, highlights, and image cutouts create variety inside one system.' },
        ] },
      { type: 'cards', label: 'Process', title: 'From content objective to final composition.', cols: 4, numbered: true,
        items: [
          { t: 'Define content pillars', d: 'Career education, skill building, confidence, community storytelling, and campaign moments.' },
          { t: 'Write the hook first', d: 'Each post starts with one takeaway; copy and hierarchy are built around it.' },
          { t: 'Art-direct the scene', d: 'Each composition is built in Figma, combining type, imagery, and brand elements.' },
          { t: 'Systemize & refine', d: 'Spacing, contrast, type, and rhythm are tuned so every post feels distinct yet clearly NextStep.' },
        ] },
      { type: 'images', label: 'The feed', cols: 1, items: [{ src: 'cs-ns-closing.jpg', alt: 'NextStep social media posts' }] },
      { type: 'quote', quote: "A strong social identity shouldn't make every post look identical. It should make different stories feel like they come from the same brand.",
        body: 'Creating NextStep from scratch let me work as both designer and content strategist: deciding what deserves attention first, how much information belongs on each visual, and which elements should repeat to build recognition.' },
    ],
  },

